mapper.select:
SELECT CAST(t.k1 AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS aggregate_type, CAST(t.k2 AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS aggregate_id, CAST(t.k3 AS SIGNED) AS aggregate_version, CAST(t.k4 AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS event_type, t.k1_orig AS aggregate_type_orig, t.k2_orig AS aggregate_id_orig, t.k3_orig AS aggregate_version_orig, t.k4_orig AS event_type_orig, DENSE_RANK() OVER (ORDER BY t.k1, t.k2, t.k3, t.k4) AS grp FROM (
SELECT CAST(#{k.aggregateType} AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS k1, CAST(#{k.aggregateId} AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS k2, CAST(#{k.aggregateVersion} AS SIGNED) AS k3, CAST(#{k.eventType} AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS k4, #{k.aggregateType} AS k1_orig, #{k.aggregateId} AS k2_orig, CAST(#{k.aggregateVersion} AS SIGNED) AS k3_orig, #{k.eventType} AS k4_orig
) t ORDER BY t.k1, t.k2, t.k3, t.k4

SELECT CAST(t.k1 AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS task_type, CAST(t.k2 AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS idempotency_key, t.k1_orig AS task_type_orig, t.k2_orig AS idempotency_key_orig, DENSE_RANK() OVER (ORDER BY t.k1, t.k2) AS grp FROM (
SELECT CAST(#{k.taskType} AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS k1, CAST(#{k.idempotencyKey} AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_0900_ai_ci AS k2, #{k.taskType} AS k1_orig, #{k.idempotencyKey} AS k2_orig
) t ORDER BY t.k1, t.k2
